    }
    p[1] = p[0];
    reverse(p[1].begin(), p[1].end());
    solver p0(p[0]);
    solver p1(p[1]);
    int m;
    cin >> m;
    forn(i, m){
		if (i % 10 == 0){
			cout.flush();
		}
        int l, r;
        cin >> l >> r;
        --l; -- r;
        bool ans = p0.query(l, r + 1) || p1.query(n - r - 1, n - l);
        cout << (ans ? "YES\n" : "NO\n");
    }
